'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const labels={fail:'买入失败',take:'止盈',stop:'止损',expiry:'到期平仓'};
let mode='guess',card=null,stats=null,period='day',range='10',busy=false;
const fmt=(n,d=2)=>Number(n).toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000)}
async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-Practice-Token':window.PRACTICE_TOKEN}:{},body:data?JSON.stringify(data):undefined});const out=await r.json();if(!r.ok)throw Error(out.error||'本地服务异常');return out}
function buttons(){const opts=mode==='guess'?Object.entries(labels):[['buy','买入'],['skip','跳过']];$('#choices').innerHTML=opts.map(([k,v])=>`<button data-choice="${k}" ${!card||card.revealed||busy?'disabled':''}>${v}</button>`).join('');$$('[data-choice]').forEach(b=>b.onclick=()=>answer(b.dataset.choice));$('#next').disabled=busy||!!(card&&!card.revealed);$('#next').textContent=busy?'正在读取本地案例…':card?'下一张随机信号 →':'随机抽取信号 →'}
async function next(){if(busy)return;busy=true;buttons();$('#result').textContent='正在核验信号与结算结果；首次加载可能需要数秒…';try{card=await api('/api/next',{mode});renderCard();chart.reset()}catch(e){toast(e.message);$('#result').textContent=e.message}finally{busy=false;buttons()}}
async function answer(choice){if(busy||!card||card.revealed)return;busy=true;buttons();try{const out=await api('/api/answer',{id:card.id,choice});card=out.case;stats=out.stats;renderCard(out.case.correct,choice);renderStats();chart.reset()}catch(e){toast(e.message)}finally{busy=false;buttons()}}
function renderCard(correct=null,choice=null){if(!card)return;$('#empty').style.display='none';$('#stock').textContent=`${card.name}　${card.symbol}`;$('#info').textContent=`信号日 ${card.day}　｜　ATR ${fmt(card.atr*100)}%　｜　买入触发价 ≤ ${fmt(card.trigger)}　｜　${card.revealed?'后续已揭晓':'未来走势已隐藏'}`;$('#lineNote').textContent=card.levels.actual?'实际成交后保护价，已换算到图表复权坐标；竖线为实际成交后30自然日':'信号日预估价（触发价含0.2%滑点）；30日边界假定下一交易日成交，作答后校准';if(card.revealed)$('#lineNote').textContent+=card.window_complete?'；已展示完整30自然日窗口，提前退出不截断':'；窗口行情仅至'+card.display_end+'，未补造未来数据';if(!card.revealed){$('#result').textContent=mode==='guess'?'仅看左侧历史走势，选择一个结局。':'买入后按策略自动结算；跳过则本次净值不变。'}else{const r=card.result,t=r.trade;const heading=mode==='guess'?(correct?'✓ 猜对了':'这次没有猜中'):(choice==='buy'?'已买入并自动结算':'已跳过，净值不变');$('#result').innerHTML=`${heading}<br><strong>${labels[r.reason]}</strong><br>${t?`成交 ${esc(t.entry_date)} · ¥${fmt(t.entry_price,4)}<br>平仓 ${esc(t.exit_date)} · ¥${fmt(t.exit_price,4)}<br>扣费单笔收益 <b class="${r.ret>=0?'red':'green'}">${r.ret>=0?'+':''}${fmt(r.ret*100)}%</b>`:`未形成持仓，收益为0。<br>窗口未成交 ${r.failure_details.expired_entry_orders} · 容量限制 ${r.failure_details.capacity_limited_orders} · 整手限制 ${r.failure_details.below_100_share_orders}`}<br><small>这是历史日线模拟结果，不是真实券商逐笔成交。</small>`}chart.draw()}
function renderStats(){if(!stats)return;$('#scoreTitle').textContent=mode==='guess'?'分类准确率':'练习净值';if(mode==='guess'){$('#stats').innerHTML=`<div class="stat-row"><span>全部猜对 / 已作答</span><strong>${stats.correct} / ${stats.total}</strong></div>`+Object.entries(labels).map(([k,v])=>`<div class="stat-row"><span>${v}</span><strong>${stats.counts[k].correct} / ${stats.counts[k].total}</strong></div>`).join('')+'<p>分母按实际结局分类；尚未作答的题不计入。</p>'}else{$('#stats').innerHTML=`<div class="stat-row"><span>当前净值</span><strong>${fmt(stats.nav,4)}</strong></div><div class="stat-row"><span>累计练习收益</span><strong>${fmt((stats.nav-1)*100)}%</strong></div><div class="stat-row"><span>操作次数（含跳过）</span><strong>${stats.journal.length}</strong></div><p>单笔净收益复利；随机题目练习成绩，非五槽账户收益。</p>`}drawNav()}
$$('[data-mode]').forEach(b=>b.onclick=()=>{if(busy)return;mode=b.dataset.mode;card=null;$$('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));$('#equityPanel').hidden=mode!=='trade';$('#modeTitle').textContent=mode==='guess'?'READ THE PAST. GUESS THE NEXT.':'ONE DECISION. ONE EQUITY STEP.';$('#decisionTitle').textContent=mode==='guess'?'这张信号，结局会是什么？':'这张信号，你会买入吗？';$('#stock').textContent='准备抽取信号卡';$('#info').textContent='未答题会保留，切回来可继续同一张；两个模式独立计分';$('#result').textContent='点击随机抽取信号开始';$('#readout').textContent='抽题后显示OHLC及成交量';$('#lineNote').textContent='虚线为信号时可得的预估，不提前泄露成交日期与价格';$('#empty').style.display='flex';chart.draw();buttons();renderStats()});
$('#next').onclick=next;
$$('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period;$$('[data-period]').forEach(x=>x.classList.toggle('active',x===b));chart.reset()});
$$('[data-range]').forEach(b=>b.onclick=()=>{range=b.dataset.range;$$('[data-range]').forEach(x=>x.classList.toggle('active',x===b));drawNav()});
const DAY=86400000,time=s=>Date.parse(s+'T00:00:00Z');
function weekly(bars){const groups=new Map();for(const b of bars){const d=new Date(time(b.time)),shift=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-shift);const key=d.toISOString().slice(0,10);if(!groups.has(key))groups.set(key,{...b});else{const w=groups.get(key);w.high=Math.max(w.high,b.high);w.low=Math.min(w.low,b.low);w.close=b.close;w.volume+=b.volume;w.time=b.time}}return [...groups.values()]}
function tradingAxis(c,p='day'){
 const last=c.bars.at(-1).time;
 const dates=[...new Set([...c.bars.map(b=>b.time),...(c.axis_sessions||[]).filter(d=>d>last)])].sort();
 const key=d=>{if(p==='day')return d;const dt=new Date(time(d));dt.setUTCDate(dt.getUTCDate()-(dt.getUTCDay()+6)%7);return dt.toISOString().slice(0,10)};
 const groups=new Map();for(const d of dates)groups.set(key(d),d);
 const keys=[...groups.keys()],labels=[...groups.values()],positions=new Map(keys.map((k,i)=>[k,i]));
 const position=d=>{const k=key(d);if(positions.has(k))return positions.get(k);let lo=0,hi=keys.length;while(lo<hi){const mid=(lo+hi)>>1;if(keys[mid]<=k)lo=mid+1;else hi=mid}return Math.max(0,lo-1)};
 return {length:keys.length,labels,position};
}
class Candles{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.domain=null;this.pointer=null;this.drag=null;new ResizeObserver(()=>this.draw()).observe(canvas.parentElement);canvas.addEventListener('wheel',e=>{e.preventDefault();this.zoom(e.deltaY<0?.8:1.25,e.offsetX)},{passive:false});canvas.addEventListener('pointerdown',e=>{this.drag={x:e.offsetX,domain:[...this.domain||[0,1]]};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{this.pointer={x:e.offsetX,y:e.offsetY};if(this.drag&&this.domain){const shift=(this.drag.x-e.offsetX)/(this.w-100)*(this.drag.domain[1]-this.drag.domain[0]);this.domain=this.drag.domain.map(v=>v+shift);this.clamp()}this.draw()});canvas.addEventListener('pointerup',()=>this.drag=null);canvas.addEventListener('pointercancel',()=>this.drag=null);canvas.addEventListener('pointerleave',()=>{this.pointer=null;this.draw()});canvas.addEventListener('dblclick',()=>this.reset());canvas.addEventListener('keydown',e=>{if(['+','=','-','ArrowLeft','ArrowRight','0'].includes(e.key)){e.preventDefault();if(e.key==='0')this.reset();else if(e.key==='-'||e.key==='+'||e.key==='=')this.zoom(e.key==='-'?1.25:.8);else if(this.domain){const dx=(this.domain[1]-this.domain[0])*.1*(e.key==='ArrowLeft'?-1:1);this.domain=this.domain.map(v=>v+dx);this.clamp();this.draw()}}})}
 reset(){if(!card){this.domain=null;this.draw();return}const axis=tradingAxis(card,period);this.domain=[-3,Math.max(axis.position(card.levels.deadline)+6,axis.position(card.bars.at(-1).time)+5)];this.pointer=null;this.draw()}
 clamp(){if(!card||!this.domain)return;const earliest=-10,latest=tradingAxis(card,period).length+15;const span=this.domain[1]-this.domain[0];if(this.domain[0]<earliest)this.domain=[earliest,earliest+span];if(this.domain[1]>latest)this.domain=[latest-span,latest]}
 zoom(f,px){if(!this.domain)return;const [a,b]=this.domain,ratio=px===undefined?.5:Math.max(0,Math.min(1,(px-12)/(this.w-100)));const span=Math.max(period==='week'?8:10,Math.min(tradingAxis(card,period).length+25,(b-a)*f)),anchor=a+(b-a)*ratio;this.domain=[anchor-span*ratio,anchor+span*(1-ratio)];this.clamp();this.draw()}
 draw(){const canvas=this.canvas,ctx=this.ctx,dpr=window.devicePixelRatio||1;this.w=canvas.clientWidth;this.h=canvas.clientHeight;if(!this.w||!this.h)return;canvas.width=this.w*dpr;canvas.height=this.h*dpr;ctx.scale(dpr,dpr);ctx.fillStyle='#0e1826';ctx.fillRect(0,0,this.w,this.h);if(!card||!card.bars.length)return;if(!this.domain){this.reset();return}const bars=period==='week'?weekly(card.bars):card.bars;const axis=tradingAxis(card,period);const [a,b]=this.domain,L=12,R=this.w-91,T=22,B=this.h*.7,V=this.h*.78,VB=this.h-34,x=t=>L+(axis.position(t)-a)/(b-a)*(R-L);const visible=bars.filter(q=>axis.position(q.time)>=a&&axis.position(q.time)<=b);const levels=card.levels;let lo=Math.min(...visible.map(q=>q.low),levels.stop),hi=Math.max(...visible.map(q=>q.high),levels.take);const pad=Math.max((hi-lo)*.08,hi*.002);lo-=pad;hi+=pad;const y=p=>T+(hi-p)/(hi-lo)*(B-T);ctx.font='11px Consolas,monospace';ctx.lineWidth=1;ctx.strokeStyle='#223249';ctx.fillStyle='#7890af';for(let i=0;i<=5;i++){const py=T+(B-T)*i/5;ctx.beginPath();ctx.moveTo(L,py);ctx.lineTo(R,py);ctx.stroke();ctx.fillText(fmt(hi-(hi-lo)*i/5),R+9,py+4)}const maxVol=Math.max(1,...visible.map(q=>q.volume));const candleWidth=Math.max(1,Math.min(16,(R-L)/(b-a)*.72));ctx.save();ctx.beginPath();ctx.rect(L,T,R-L,VB-T);ctx.clip();const sx=x(levels.start),ex=x(levels.deadline);ctx.fillStyle='#507da416';ctx.fillRect(sx,y(levels.take),ex-sx,y(levels.stop)-y(levels.take));for(const q of visible){const px=x(q.time),color=q.close>=q.open?'#ef7380':'#58c79f';ctx.strokeStyle=color;ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(px,y(q.high));ctx.lineTo(px,y(q.low));ctx.stroke();const bodyY=y(Math.max(q.open,q.close)),bodyH=Math.max(1,Math.abs(y(q.open)-y(q.close)));ctx.fillRect(px-candleWidth/2,bodyY,candleWidth,bodyH);const vh=q.volume/maxVol*(VB-V);ctx.globalAlpha=.7;ctx.fillRect(px-candleWidth/2,VB-vh,candleWidth,vh);ctx.globalAlpha=1}ctx.setLineDash([5,5]);for(const [key,color] of [['take','#f17683'],['stop','#60cba4'],['entry','#87b9fa']]){ctx.strokeStyle=color;ctx.beginPath();ctx.moveTo(sx,y(levels[key]));ctx.lineTo(ex,y(levels[key]));ctx.stroke()}ctx.strokeStyle='#e7bb72';ctx.beginPath();ctx.moveTo(ex,y(levels.take));ctx.lineTo(ex,y(levels.stop));ctx.stroke();ctx.beginPath();ctx.moveTo(sx,y(levels.take));ctx.lineTo(sx,y(levels.stop));ctx.stroke();ctx.strokeStyle='#7d93b6';ctx.beginPath();ctx.moveTo(x(card.day),T);ctx.lineTo(x(card.day),VB);ctx.stroke();ctx.restore();ctx.setLineDash([]);ctx.fillStyle='#8ba4c4';ctx.fillText('成交量（股）　'+(period==='week'?'周累计':'日成交'),L,V-8);for(const [key,label,color] of [['take','止盈','#f17683'],['stop','止损','#60cba4'],['entry','入场','#87b9fa']]){const px=Math.max(L+4,Math.min(R-100,ex+5)),py=y(levels[key]);ctx.fillStyle='#0e1826e8';ctx.fillRect(px,py-13,104,15);ctx.fillStyle=color;ctx.fillText(label+' '+fmt(levels[key]),px+3,py-2)}if(ex>=L&&ex<=R){ctx.fillStyle='#e7bb72';ctx.fillText('30日 '+levels.deadline.slice(5),Math.max(L,Math.min(R-100,ex-40)),B+18)}if(x(card.day)>=L&&x(card.day)<=R){ctx.fillStyle='#a9bfdf';ctx.fillText('信号日',Math.max(L,x(card.day)-18),T-6)}for(let i=0;i<=4;i++){const idx=Math.round(a+(b-a)*i/4),px=L+(R-L)*i/4;ctx.fillStyle='#7890af';if(axis.labels[idx])ctx.fillText(axis.labels[idx],Math.min(R-60,px),this.h-10)}if(this.pointer){const p=this.pointer;if(p.x>=L&&p.x<=R&&p.y>=T&&p.y<=VB){const nearest=bars.reduce((best,q)=>Math.abs(x(q.time)-p.x)<Math.abs(x(best.time)-p.x)?q:best,bars[0]);ctx.setLineDash([3,4]);ctx.strokeStyle='#a2b9d280';ctx.beginPath();ctx.moveTo(p.x,T);ctx.lineTo(p.x,VB);ctx.moveTo(L,p.y);ctx.lineTo(R,p.y);ctx.stroke();ctx.setLineDash([]);if(Math.abs(x(nearest.time)-p.x)<Math.max(15,candleWidth*2))$('#readout').textContent=`${period==='week'?'周截至':'日期'} ${nearest.time}　开 ${fmt(nearest.open)}　高 ${fmt(nearest.high)}　低 ${fmt(nearest.low)}　收 ${fmt(nearest.close)}　量 ${fmt(nearest.volume,0)} 股`;else $('#readout').textContent=card.revealed?'该位置没有K线数据':'未来区间 · 作答后揭晓';if(p.y<=B){ctx.fillStyle='#b6c9e4';ctx.fillText(fmt(hi-(p.y-T)/(B-T)*(hi-lo)),R+6,p.y-5)}}}else $('#readout').textContent=`${period==='week'?'周线（本周仅聚合已展示日线）':'日线'} · ${visible.length}根可见K线 · 信号 ${card.day}`;
 }
}
const chart=new Candles($('#candles'));$('#zoomIn').onclick=()=>chart.zoom(.8);$('#zoomOut').onclick=()=>chart.zoom(1.25);$('#reset').onclick=()=>chart.reset();
function practiceNavAxis(values){
 const lo=Math.min(...values),hi=Math.max(...values),pad=Math.max(.01,(hi-lo)*.08);
 // Integer fifths avoid drift: 1.0 + k*0.2. Always five equal-spaced lines.
 const lower=Math.floor((lo-pad)*5+1e-9),upper=Math.ceil((hi+pad)*5-1e-9);
 const step=Math.max(1,Math.ceil((upper-lower)/4));
 let bottom=Math.floor((lower+upper-4*step)/2);
 if(lo>=0)bottom=Math.max(0,bottom);
 if(bottom>lower&&lower>=0)bottom=lower;
 if(bottom+4*step<upper)bottom=upper-4*step;
 const ticks=Array.from({length:5},(_,i)=>(bottom+(4-i)*step)/5);
 return {min:ticks[4],max:ticks[0],ticks};
}
function drawNav(){if(!stats||$('#equityPanel').hidden)return;const all=stats.journal,n=range==='all'?all.length:Number(range),rows=all.slice(-n),previous=all.length>rows.length?all[all.length-rows.length-1]:null,base=previous?previous.nav:1;const values=[base,...rows.map(r=>r.nav)],canvas=$('#navChart'),ctx=canvas.getContext('2d'),w=canvas.clientWidth,h=230,dpr=window.devicePixelRatio||1;if(!w)return;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);const {min,max,ticks}=practiceNavAxis(values),x=i=>55+i/Math.max(1,values.length-1)*(w-80),y=v=>15+(max-v)/(max-min)*180;ctx.font='11px Consolas,monospace';for(const v of ticks){const py=y(v);ctx.strokeStyle='#28394f';ctx.beginPath();ctx.moveTo(55,py);ctx.lineTo(w-20,py);ctx.stroke();ctx.fillStyle='#8aa1bf';ctx.fillText(v.toFixed(1),4,py+4)}ctx.strokeStyle='#8dbdfa';ctx.lineWidth=2;ctx.beginPath();values.forEach((v,i)=>i?ctx.lineTo(x(i),y(v)):ctx.moveTo(x(i),y(v)));ctx.stroke();values.forEach((v,i)=>{ctx.fillStyle='#bfd8ff';ctx.beginPath();ctx.arc(x(i),y(v),2.8,0,Math.PI*2);ctx.fill()});ctx.fillStyle='#8aa1bf';ctx.fillText('第'+(previous?previous.id:0)+'次',55,221);ctx.fillText('第'+(all.at(-1)?.id||0)+'次',Math.max(55,w-90),221);$('#journal').innerHTML='<table><thead><tr><th>操作</th><th>选择</th><th>实际结局</th><th>本次收益</th><th>净值</th></tr></thead><tbody>'+rows.slice().reverse().map(r=>`<tr><td>#${r.id}</td><td>${r.choice==='buy'?'买入':'跳过'}</td><td>${labels[r.reason]}</td><td class="${r.ret>=0?'red':'green'}">${fmt(r.ret*100)}%</td><td>${fmt(r.nav,4)}</td></tr>`).join('')+'</tbody></table>'}
window.addEventListener('resize',drawNav);buttons();api('/api/stats').then(s=>{stats=s;renderStats()}).catch(e=>toast(e.message));
